(function (window, document) {
    'use strict';

    var STORAGE_THEME = 'cvixClientThemeMode';
    var STORAGE_SIDEBAR = 'cvixClientSidebarCollapsed';

    function qs(sel, ctx) {
        return (ctx || document).querySelector(sel);
    }

    function qsa(sel, ctx) {
        return Array.prototype.slice.call((ctx || document).querySelectorAll(sel));
    }

    function applyTheme(mode) {
        document.body.setAttribute('data-cv-theme', mode || 'system');
        qsa('.cv-theme-btn').forEach(function (btn) {
            btn.classList.toggle('active', btn.getAttribute('data-cv-theme-mode') === mode);
        });
        try {
            localStorage.setItem(STORAGE_THEME, mode || 'system');
        } catch (e) {}
    }

    function initTheme() {
        var saved = 'system';
        try {
            saved = localStorage.getItem(STORAGE_THEME) || 'system';
        } catch (e) {}
        applyTheme(saved);
        qsa('.cv-theme-btn').forEach(function (btn) {
            btn.addEventListener('click', function () {
                applyTheme(btn.getAttribute('data-cv-theme-mode'));
            });
        });
    }

    function initSidebar() {
        var sidebar = qs('#cv-sidebar');
        var overlay = qs('#cv-sidebar-overlay');
        var toggle = qs('#cv-sidebar-toggle');
        var mobileMenu = qs('#cv-mobile-menu');
        var mobileMenuBottom = qs('#cv-mobile-menu-bottom');

        function openMobile() {
            if (sidebar) sidebar.classList.add('cv-sidebar-open');
            if (overlay) overlay.hidden = false;
        }

        function closeMobile() {
            if (sidebar) sidebar.classList.remove('cv-sidebar-open');
            if (overlay) overlay.hidden = true;
        }

        if (mobileMenu) mobileMenu.addEventListener('click', openMobile);
        if (mobileMenuBottom) mobileMenuBottom.addEventListener('click', openMobile);
        if (overlay) overlay.addEventListener('click', closeMobile);

        if (toggle) {
            toggle.addEventListener('click', function () {
                var collapsed = !document.body.classList.contains('cv-sidebar-collapsed');
                document.body.classList.toggle('cv-sidebar-collapsed', collapsed);
                toggle.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
                try {
                    localStorage.setItem(STORAGE_SIDEBAR, collapsed ? '1' : '0');
                } catch (e) {}
            });
        }

        try {
            if (localStorage.getItem(STORAGE_SIDEBAR) === '1') {
                document.body.classList.add('cv-sidebar-collapsed');
            }
        } catch (e) {}
    }

    function initCounters() {
        if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
            return;
        }
        qsa('[data-cv-counter]').forEach(function (el) {
            var target = parseInt(el.getAttribute('data-cv-counter'), 10) || 0;
            if (target <= 0) return;
            var duration = 800;
            var start = 0;
            var startTime = null;
            function step(ts) {
                if (!startTime) startTime = ts;
                var progress = Math.min((ts - startTime) / duration, 1);
                var value = Math.floor(progress * target);
                el.textContent = String(value);
                if (progress < 1) window.requestAnimationFrame(step);
                else el.textContent = String(target);
            }
            window.requestAnimationFrame(step);
        });
    }

    function showToast(message, type) {
        var root = qs('#cv-toast-root');
        if (!root || !message) return;
        var toast = document.createElement('div');
        toast.className = 'cv-toast cv-toast-' + (type || 'info');
        toast.setAttribute('role', 'alert');
        toast.textContent = message;
        root.appendChild(toast);
        window.setTimeout(function () {
            toast.style.opacity = '0';
            window.setTimeout(function () {
                if (toast.parentNode) toast.parentNode.removeChild(toast);
            }, 300);
        }, 4500);
    }

    window.CentralVixClient = {
        toast: showToast,
        finalizeTable: finalizeTable
    };

    function finalizeTable(tableId, orderFn) {
        if (typeof jQuery === 'undefined') {
            return;
        }
        var $table = jQuery('#' + tableId);
        var $loading = jQuery('#tableLoading');
        try {
            if ($table.length && jQuery.fn.DataTable && jQuery.fn.DataTable.isDataTable($table)) {
                var table = $table.DataTable();
                if (typeof orderFn === 'function') {
                    orderFn(table);
                }
                table.draw(false);
            }
        } catch (e) {
            /* tablelist.tpl já inicializou — só exibir */
        }
        $table.removeClass('w-hidden').addClass('cv-table-ready').css('display', '');
        if ($loading.length) {
            $loading.addClass('cv-hidden').hide();
        }
    }

    function initAccountDropdown() {
        var wrap = qs('#cv-account-dropdown');
        var btn = qs('#cv-account-menu-btn');
        var menu = wrap ? wrap.querySelector('.dropdown-menu') : null;
        if (!btn || !menu) {
            return;
        }
        btn.addEventListener('click', function (e) {
            e.preventDefault();
            e.stopPropagation();
            var isOpen = menu.classList.contains('show');
            qsa('.dropdown-menu.show').forEach(function (m) {
                m.classList.remove('show');
            });
            qsa('.dropdown.show').forEach(function (el) {
                el.classList.remove('show');
            });
            if (!isOpen) {
                menu.classList.add('show');
                wrap.classList.add('show');
                btn.setAttribute('aria-expanded', 'true');
            } else {
                btn.setAttribute('aria-expanded', 'false');
            }
        });
        document.addEventListener('click', function (e) {
            if (!e.target.closest('#cv-account-dropdown')) {
                menu.classList.remove('show');
                wrap.classList.remove('show');
                btn.setAttribute('aria-expanded', 'false');
            }
        });
    }

    function initBootstrapUi() {
        if (typeof jQuery === 'undefined') {
            initAccountDropdown();
            return;
        }
        if (jQuery.fn.dropdown) {
            jQuery('[data-toggle="dropdown"]').dropdown();
        } else {
            initAccountDropdown();
        }

        var $notif = jQuery('#accountNotifications');
        var $content = jQuery('#accountNotificationsContent');
        if ($notif.length && $content.length && jQuery.fn.popover) {
            $notif.popover({
                html: true,
                sanitize: false,
                content: function () {
                    return $content.html();
                },
                trigger: 'click',
                container: 'body',
                placement: 'bottom'
            }).on('shown.bs.popover', function () {
                jQuery('body').on('click.cvPopover', function (e) {
                    if (!jQuery(e.target).closest('.popover, #accountNotifications').length) {
                        $notif.popover('hide');
                    }
                });
            }).on('hidden.bs.popover', function () {
                jQuery('body').off('click.cvPopover');
            });
        }
    }

    function initTableSafetyNet() {
        if (typeof jQuery === 'undefined') {
            return;
        }
        jQuery(document).ready(function () {
            window.setTimeout(function () {
                qsa('.cv-table-card table.table-list[id]').forEach(function (el) {
                    if (el.id) {
                        finalizeTable(el.id);
                    }
                });
            }, 150);
        });
    }

    function initWhatsApp() {
        var wrap = qs('#cv-whatsapp-wrap');
        var btn = qs('#cv-whatsapp-btn');
        if (!wrap || !btn) return;
        var phone = wrap.getAttribute('data-whatsapp');
        if (!phone) {
            wrap.hidden = true;
            return;
        }
        var digits = phone.replace(/\D/g, '');
        if (!digits) {
            wrap.hidden = true;
            return;
        }
        btn.href = 'https://wa.me/' + digits;
        wrap.hidden = false;
    }

    function initFlashToToast() {
        qsa('.alert-success, .successbox').forEach(function (el) {
            var text = (el.textContent || '').trim();
            if (text) showToast(text, 'success');
        });
        qsa('.alert-danger, .errorbox').forEach(function (el) {
            var text = (el.textContent || '').trim();
            if (text) showToast(text, 'error');
        });
    }

    function initPixStyling() {
        qsa('img[alt*="pix" i], img[alt*="PIX" i]').forEach(function (img) {
            if (img.parentElement && !img.parentElement.classList.contains('cv-pix-box')) {
                img.parentElement.classList.add('cv-pix-box');
            }
        });
    }

    document.addEventListener('DOMContentLoaded', function () {
        initTheme();
        initSidebar();
        initCounters();
        initWhatsApp();
        initFlashToToast();
        initPixStyling();
        initBootstrapUi();
        initTableSafetyNet();
    });
})(window, document);
